import{_ as o,o as t,c as n,l as a,t as i,N as r}from"./chunks/framework.Bbd9fWQx.js";const v=JSON.parse('{"title":"iconvconfig | x-cmd man (man8) | create iconv module configuration cache","titleTemplate":false,"description":"x-cmd man (man8 Manual Page) | iconvconfig - create iconv module configuration cache","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"iconvconfig | x-cmd man (man8) | create iconv module configuration cache"}],["meta",{"name":"og:description","content":"x-cmd man (man8 Manual Page) | iconvconfig - create iconv module configuration cache"}]]},"headers":[],"params":{"isMan":true,"man":"iconvconfig","category":"man8","desc":"create iconv module configuration cache"},"relativePath":"man8/iconvconfig.md","filePath":"man8/iconvconfig.md"}'),s={name:"man8/iconvconfig.md"},c={class:"visually-hidden"},d=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>iconvconfig - create iconv module configuration cache</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>iconvconfig</strong> [<em>options</em>] [<em>directory</em>]...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <strong>iconv</strong>(3) function internally uses <em>gconv</em> modules to convert to and from a character set. A configuration file is used to determine the needed modules for a conversion. Loading and parsing such a configuration file would slow down programs that use <strong>iconv</strong>(3), so a caching mechanism is employed.</p><p>The <strong>iconvconfig</strong> program reads iconv module configuration files and writes a fast-loading gconv module configuration cache file.</p><p>In addition to the system provided gconv modules, the user can specify custom gconv module directories with the environment variable <strong>GCONV_PATH</strong>. However, iconv module configuration caching is used only when the environment variable <strong>GCONV_PATH</strong> is not set.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><dl><dt><strong>--nostdlib</strong></dt><dd>Do not search the system default gconv directory, only the directories provided on the command line.</dd><dt><strong>--output=</strong> <em>outputfile</em> <br> <strong>-o</strong> <em>outputfile</em></dt><dd>Use <em>outputfile</em> for output instead of the system default cache location.</dd><dt><strong>--prefix=</strong> <em>pathname</em></dt><dd>Set the prefix to be prepended to the system pathnames. See FILES, below. By default, the prefix is empty. Setting the prefix to <em>foo</em>, the gconv module configuration would be read from <em>foo/usr/lib/gconv/gconv-modules</em> and the cache would be written to <em>foo/usr/lib/gconv/gconv-modules.cache</em>.</dd><dt><strong>--help</strong> <br> <strong>-?</strong></dt><dd>Print a usage summary and exit.</dd><dt><strong>--usage</strong></dt><dd>Print a short usage summary and exit.</dd><dt><strong>--version</strong> <br> <strong>-V</strong></dt><dd>Print the version number, license, and disclaimer of warranty for <strong>iconv</strong>.</dd></dl><h2 id="exit-status" tabindex="-1">EXIT STATUS <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;EXIT STATUS&quot;">​</a></h2><p>Zero on success, nonzero on errors.</p><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><dl><dt><em>/usr/lib/gconv</em></dt><dd>Usual default gconv module path.</dd><dt><em>/usr/lib/gconv/gconv-modules</em></dt><dd>Usual system default gconv module configuration file.</dd><dt><em>/usr/lib/gconv/gconv-modules.cache</em></dt><dd>Usual system gconv module configuration cache.</dd></dl><p>Depending on the architecture, the above files may instead be located at directories with the path prefix <em>/usr/lib64</em>.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>iconv</strong>(1), <strong>iconv</strong>(3)</p>',17);function m(e,l,u,g,h,f){return t(),n("div",null,[a("h1",c,i(e.$params.man),1),d])}const b=o(s,[["render",m]]);export{v as __pageData,b as default};
